    effect eFatigue = EffectLinkEffects(EffectAbilityDecrease(ABILITY_STRENGTH, 2), EffectAbilityDecrease(ABILITY_DEXTERITY, 2));
    eFatigue = EffectLinkEffects(eFatigue, EffectMovementSpeedDecrease(50));

